#include "DynamicRepairSimulator.hpp"
#include "SimulationConfig.hpp"

#include <algorithm>
#include <array>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <map>
#include <optional>
#include <set>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

namespace {
using namespace dynamic_spare;
namespace fs = std::filesystem;
constexpr std::size_t S = 4;
constexpr std::array<char, S> ROLE{{'A','B','C','D'}};
constexpr std::array<const char *, 4> ACTION{{"LOCAL","RELEASE","BORROW","RELEASE_BORROW"}};
constexpr std::array<std::size_t, 4> RC{{0,1,2,3}};
constexpr std::array<std::size_t, 4> R{{0,1,2,0}};
struct Row { std::map<std::string,std::string> v; };
struct Group { std::size_t id; std::string raw; FaultGroup f; };
struct Path { std::size_t count=0; std::optional<std::size_t> id; std::array<std::size_t,S> s{}; };
void need(bool x, const std::string &m) { if (!x) throw std::runtime_error(m); }
std::vector<std::string> split(const std::string &s, char c) { std::vector<std::string> x; std::size_t begin=0; for (;;) { const std::size_t end=s.find(c,begin); x.push_back(s.substr(begin,end==std::string::npos ? std::string::npos : end-begin)); if(end==std::string::npos) break; begin=end+1; } return x; }
std::vector<Row> csv(const fs::path &p) {
    std::ifstream in(p); need(in.good(), "cannot open "+p.string()); std::string l; need(bool(std::getline(in,l)), "empty "+p.string()); auto h=split(l,','); std::vector<Row> out;
    while (std::getline(in,l)) { auto f=split(l,','); need(f.size()==h.size(), "CSV field mismatch "+p.string()); Row r; for (std::size_t i=0;i<h.size();++i) r.v[h[i]]=f[i]; out.push_back(std::move(r)); } return out;
}
std::map<std::size_t,Row> index(const std::vector<Row> &rows) { std::map<std::size_t,Row> out; for (const auto &r:rows) { auto id=std::stoull(r.v.at("group_id")); need(out.emplace(id,r).second,"duplicate group id"); } return out; }
std::string one(const Fault &f) { return std::to_string(f.HBMID)+":"+std::to_string(f.ChannelID)+":"+std::to_string(f.BankID)+":"+std::to_string(f.SubarrayGroupID)+":"+std::to_string(f.SubarrayID)+":"+std::to_string(f.r)+":"+std::to_string(f.c); }
std::string encode(const FaultGroup &f) { std::ostringstream o; for (std::size_t sa=0;sa<S;++sa) { if(sa)o<<'|'; for(std::size_t i=0;i<f[sa].size();++i) {if(i)o<<';';o<<one(f[sa][i]);}} return o.str(); }
Group decode(const Row &r) {
    Group g{std::stoull(r.v.at("group_id")),r.v.at("sa_local_faults"),{}}; auto b=split(g.raw,'|'); need(b.size()==S,"four SA buckets required");
    for(std::size_t sa=0;sa<S;++sa) if(!b[sa].empty()) for(const auto &e:split(b[sa],';')) { auto x=split(e,':'); need(x.size()==7,"bad frozen fault"); Fault f{}; f.HBMID=std::stoi(x[0]);f.ChannelID=std::stoi(x[1]);f.BankID=std::stoi(x[2]);f.SubarrayGroupID=std::stoi(x[3]);f.SubarrayID=std::stoi(x[4]);f.r=std::stoi(x[5]);f.c=std::stoi(x[6]);need(f.SubarrayID==int(sa),"SA encoding mismatch");g.f[sa].push_back(f); }
    need(encode(g.f)==g.raw,"reconstructed faults differ from frozen representation"); return g;
}
SimulationConfig config(int n,bool row) { SimulationConfig c; c.spareRows=n;c.spareColumns=n;c.sharedRows=1;c.sharedColumns=row?0:1;c.layout=GroupLayout::Grid2x2;c.topology=SharingTopology::Directional;c.solutionTakePolicy=row?SolutionTakePolicy::Grid2x2RowStaticGlobal:SolutionTakePolicy::Hyp02StaticGlobal;c.usePaperCamReuseCapacity=true;return c; }
bool valid(const RepairAttemptResult&a){return a.repairSuccess&&a.tileSolutionState.has_value()&&!a.validCandidateOptions.empty();}
std::optional<std::size_t> pattern(const RepairAttemptResult&a){if(!a.repairSuccess || !a.tileSolutionState.has_value() || a.validCandidateOptions.empty())return std::nullopt;std::size_t p=0;for(const auto&o:a.validCandidateOptions){const std::size_t candidate=o.candidateIndex+1;if(p==0 || candidate<p)p=candidate;}return p;}
bool legal(const std::array<std::size_t,S>&s){auto rel=[&](int x){return s[x]==1||s[x]==3;};auto bor=[&](int x){return s[x]==2||s[x]==3;};return(!bor(2)||rel(0))&&(!bor(1)||rel(3))&&(!bor(0)||rel(1))&&(!bor(3)||rel(2));}
Path paths(const GroupRepairResult&r,const std::array<std::size_t,4>&map){Path p;std::size_t id=0;for(std::size_t x=0;x<256;++x){std::array<std::size_t,S>s{{x&3,(x>>2)&3,(x>>4)&3,(x>>6)&3}};if(!legal(s))continue;bool ok=true;for(std::size_t sa=0;sa<S;++sa)ok=ok&&map[s[sa]]<r.attemptsBySubarray[sa].size()&&valid(r.attemptsBySubarray[sa][map[s[sa]]]);if(ok){++p.count;if(!p.id){p.id=id;p.s=s;}}++id;}need(id==81,"static path count must be 81");return p;}
std::string formatTuple(const Path&p){if(!p.id)return"-";std::ostringstream o;for(std::size_t sa=0;sa<S;++sa){if(sa)o<<':';o<<ACTION[p.s[sa]];}return o.str();}
std::string pathDiagnostics(const GroupRepairResult&r,const std::array<std::size_t,4>&map,const Path&p){std::size_t invalid=0, illegal=0;for(std::size_t x=0;x<256;++x){std::array<std::size_t,S>s{{x&3,(x>>2)&3,(x>>4)&3,(x>>6)&3}};if(!legal(s)){++illegal;continue;}bool ok=true;for(std::size_t sa=0;sa<S;++sa)ok=ok&&valid(r.attemptsBySubarray[sa].at(map[s[sa]]));if(!ok)++invalid;}return std::string(p.id?"PASS":"NO_FEASIBLE_STATIC_PATH")+";legal_paths=81;feasible_paths="+std::to_string(p.count)+";sa_analyzer_config_invalid_paths="+std::to_string(invalid)+";borrow_without_matching_release_raw_tuples="+std::to_string(illegal)+";resource_type_mismatch=0;donor_unavailable=0;other_physical_constraint=0";}
std::string geom(const std::vector<Fault>&f){std::map<int,std::size_t>rs,cs;for(const auto&x:f){++rs[x.r];++cs[x.c];}auto collision=[](const auto&m){std::size_t n=0;for(const auto&x:m)if(x.second>1)n+=x.second-1;return n;};auto max=[](const auto&m){std::size_t n=0;for(const auto&x:m)n=std::max(n,x.second);return n;};return"fault_count="+std::to_string(f.size())+";unique_rows="+std::to_string(rs.size())+";unique_columns="+std::to_string(cs.size())+";same_row_collision_count="+std::to_string(collision(rs))+";same_column_collision_count="+std::to_string(collision(cs))+";max_row_multiplicity="+std::to_string(max(rs))+";max_column_multiplicity="+std::to_string(max(cs));}
int rcCfg(std::size_t sa,std::size_t slot){constexpr std::array<std::array<int,4>,4>m{{{{0,4,5,6}},{{0,1,2,3}},{{0,1,2,3}},{{0,4,5,6}}}};return m[sa][slot];}
std::string diag(const GroupRepairResult&r,bool row){std::ostringstream o;for(std::size_t sa=0;sa<S;++sa){if(sa)o<<'|';o<<ROLE[sa]<<':';for(std::size_t d=0;d<(row?3:4);++d){if(d)o<<';';const auto&a=r.attemptsBySubarray[sa].at(d);const auto&p=pattern(a);const char* label=row?(d==0?"2R2C":d==1?"1R2C":"3R2C"):(d==0?"LOCAL":d==1?"RELEASE":d==2?"BORROW":"RELEASE_BORROW");o<<label<<"[dense="<<d<<";logical_cfg="<<(row?(d==0?0:d==1?1:2):rcCfg(sa,d))<<";capacity="<<a.availableRows<<'R'<<a.availableColumns<<"C;valid="<<(valid(a)?1:0)<<";pattern="<<(p?std::to_string(*p):"-")<<']';}if(row)o<<";action_map=RELEASE->1R2C;LOCAL->2R2C;RELEASE_BORROW->2R2C;BORROW->3R2C";}return o.str();}
bool metadata(const GroupRepairResult&r,const Row&p){if(!r.groupRepairSuccess)return true;for(std::size_t sa=0;sa<S;++sa){std::string z(1,ROLE[sa]);if(!r.selectedConfigIds[sa]||!r.selectedPatternIds[sa]||std::to_string(*r.selectedConfigIds[sa])!=p.v.at("selected_config_"+z)||std::to_string(*r.selectedPatternIds[sa])!=p.v.at("selected_pattern_"+z))return false;}return true;}
std::string classify(const GroupRepairResult&rc,const GroupRepairResult&r,const Path&pc,const Path&pr,std::string&answer,std::string&detail){bool ro=r.groupRepairSuccess&&!rc.groupRepairSuccess,co=rc.groupRepairSuccess&&!r.groupRepairSuccess;if(!ro&&!co){answer="N/A";detail="not discordant";return"OTHER";}const auto&w=ro?r:rc;const auto&l=ro?rc:r;const auto&p=ro?pr:pc;const auto&wm=ro?R:RC;const auto&lm=ro?RC:R;for(std::size_t sa=0;sa<S;++sa){auto a=p.s[sa];const auto&wa=w.attemptsBySubarray[sa].at(wm[a]);const auto&la=l.attemptsBySubarray[sa].at(lm[a]);if(valid(wa)&&!valid(la)){detail=std::string("bottleneck_sa=")+ROLE[sa]+";action="+ACTION[a]+";winner_capacity="+std::to_string(wa.availableRows)+"R"+std::to_string(wa.availableColumns)+"C;loser_capacity="+std::to_string(la.availableRows)+"R"+std::to_string(la.availableColumns)+"C;winner_path=P"+std::to_string(*p.id);if(ro&&wa.availableRows>la.availableRows){answer="YES";return"ROW_RESOURCE_ADVANTAGE_R";}if(co&&wa.availableColumns>la.availableColumns){answer="YES";return"COLUMN_RESOURCE_ADVANTAGE_RC";}answer="NO";return"PER_SA_CONFIG_FEASIBILITY";}}answer="UNCLEAR";detail="no per-action feasibility witness";return"OTHER";}
void field(std::ofstream&o,const std::string&x,bool last=false){o<<x<<(last?'\n':',');}
}
int main(){try{
    const fs::path root="tmp/date2026/6case_1k", out=root/"analysis"/"rc_r_narrow_forensic_replay";fs::create_directories(out);std::ofstream o(out/"replay_records_v1.csv");need(o.good(),"cannot create output");
    o<<"N,F_GROUP,group_id,paired_class,sa_A_geometry,sa_B_geometry,sa_C_geometry,sa_D_geometry,rc_attempts,r_attempts,rc_feasible_path_count,r_feasible_path_count,rc_selected_path,r_selected_path,rc_selected_actions,r_selected_actions,rc_failure,r_failure,rc_path_diagnostics,r_path_diagnostics,root_cause_class,root_cause_detail,important_question_answer\n";
    const std::array<std::pair<int,int>,6> points{{{2,24},{2,28},{2,32},{2,36},{3,44},{4,40}}};DynamicRepairSimulator sim;std::size_t total=0,outcome=0,meta=0,oracle=0;std::map<std::string,std::size_t> classes,questions;std::ostringstream rep;rep<<"# DATE2026 RC_GROUP vs R_GROUP narrow forensic replay\n\nFrozen `paired_corpus_v1.csv` was replayed directly; no fault corpus was regenerated and no sweep was run.  RC/R `group_id` and `sa_local_faults` are asserted equal before every point replay.\n\n| N/F | R_ONLY | RC_ONLY |\n|---|---:|---:|\n";
    for(const auto&pt:points){int n=pt.first,f=pt.second;fs::path dir=root/("n"+std::to_string(n))/"raw"/("n"+std::to_string(n)+"_f"+std::to_string(f));auto cr=csv(dir/"g2x2_rc_group"/"paired_corpus_v1.csv");auto rcorpus=csv(dir/"g2x2_r_group"/"paired_corpus_v1.csv");need(cr.size()==rcorpus.size(),"RC/R frozen corpus size mismatch");for(std::size_t corpusIndex=0;corpusIndex<cr.size();++corpusIndex)need(cr[corpusIndex].v.at("group_id")==rcorpus[corpusIndex].v.at("group_id") && cr[corpusIndex].v.at("sa_local_faults")==rcorpus[corpusIndex].v.at("sa_local_faults"),"RC/R frozen corpus group alignment mismatch");auto rc=index(csv(dir/"g2x2_rc_group"/"paired_policy_results_v1.csv"));auto rr=index(csv(dir/"g2x2_r_group"/"paired_policy_results_v1.csv"));std::vector<std::pair<std::string,Group>> chosen;std::size_t rn=0,cn=0;for(const auto&row:cr){auto g=decode(row);bool a=rc.at(g.id).v.at("repair_success")=="1",b=rr.at(g.id).v.at("repair_success")=="1";if(b&&!a&&rn++<20)chosen.emplace_back("R_ONLY",g);if(a&&!b&&cn++<20)chosen.emplace_back("RC_ONLY",g);}rep<<"| N"<<n<<"/F"<<f<<" | "<<std::min(rn,std::size_t(20))<<" | "<<std::min(cn,std::size_t(20))<<" |\n";
    for(const auto&entry:chosen){const auto&kind=entry.first;const auto&g=entry.second;auto a=sim.run(g.f,config(n,false),g.id,false),b=sim.run(g.f,config(n,true),g.id,false);outcome+=(a.groupRepairSuccess!=(rc.at(g.id).v.at("repair_success")=="1"))+(b.groupRepairSuccess!=(rr.at(g.id).v.at("repair_success")=="1"));meta+=!metadata(a,rc.at(g.id))+!metadata(b,rr.at(g.id));auto pa=paths(a,RC),pb=paths(b,R);oracle+=(pa.id.has_value()!=a.groupRepairSuccess)+(pb.id.has_value()!=b.groupRepairSuccess);if(a.groupRepairSuccess)for(std::size_t sa=0;sa<S;++sa)oracle+=!a.selectedV2Actions[sa]||std::size_t(*a.selectedV2Actions[sa])!=pa.s[sa];if(b.groupRepairSuccess)for(std::size_t sa=0;sa<S;++sa)oracle+=!b.selectedV2Actions[sa]||std::size_t(*b.selectedV2Actions[sa])!=pb.s[sa];std::string answer,detail,klass=classify(a,b,pa,pb,answer,detail);++classes[klass];++questions[kind+"_"+answer];++total;field(o,std::to_string(n));field(o,std::to_string(f));field(o,std::to_string(g.id));field(o,kind);for(const auto&x:g.f)field(o,geom(x));field(o,diag(a,false));field(o,diag(b,true));field(o,std::to_string(pa.count));field(o,std::to_string(pb.count));field(o,pa.id?"P"+std::to_string(*pa.id):"-");field(o,pb.id?"P"+std::to_string(*pb.id):"-");field(o,formatTuple(pa));field(o,formatTuple(pb));field(o,pa.id?"":"NO_FEASIBLE_STATIC_PATH");field(o,pb.id?"":"NO_FEASIBLE_STATIC_PATH");field(o,pathDiagnostics(a,RC,pa));field(o,pathDiagnostics(b,R,pb));field(o,klass);field(o,detail);field(o,answer,true);}}
    rep<<"\n## Replay gates\n\n- REPLAYED_DISCORDANT_GROUPS: "<<total<<"\n- REPLAY_OUTCOME_MISMATCHES: "<<outcome<<"\n- SUCCESS_METADATA_MISMATCHES: "<<meta<<"\n- STATIC_ORACLE_MISMATCHES: "<<oracle<<"\n\n## Root-cause classes\n\n";for(const auto&e:classes)rep<<"- "<<e.first<<": "<<e.second<<"\n";rep<<"\n## Important diagnostic question answers\n\n";for(const auto&e:questions)rep<<"- "<<e.first<<": "<<e.second<<"\n";std::ofstream r(out/"REPORT.md");r<<rep.str();need(outcome==0,"REPLAY_OUTCOME_MISMATCHES != 0; RCA stopped");need(meta==0,"SUCCESS_METADATA_MISMATCHES != 0; RCA stopped");need(oracle==0,"STATIC_ORACLE_MISMATCHES != 0; RCA stopped");return 0;
}catch(const std::exception&e){std::cerr<<"SIXCASE_RC_R_FORENSIC_REPLAY_FAILURE: "<<e.what()<<'\n';return 1;}}
